export const POLICE_STATION_LABELS = POLICE_STATIONS.map((p) => p.label)

// Loose free-text match (no AI): find a thana whose name appears in the text.
export function findPoliceStation(text) {
  if (!text) return null
  const t = String(text).toLowerCase()
  return POLICE_STATIONS.find((p) => t.includes(p.thana.toLowerCase())) || null
}
